import type { MetadataRoute } from 'next';
/**
 * sitemap.xml — generated by Next.js. A curated list of public, indexable
 * routes, led by Pursuit, DO and Studio. Private, preview, visitor-generated
 * and redirect-source URLs stay out of this curated list.
 * Host is the canonical www origin.
 */
const BASE = 'https://www.assembl.co.nz';
const PRODUCT_PATHS = ['/pursuit', '/do', '/creative-studio'];

const CORE_PATHS = [
  '',
  ...PRODUCT_PATHS,
  '/do/install',
  '/agent-schema',
  '/ai-ready',
  // The public agent builder (per-agent share pages are deliberately not
  // listed — they're visitor-made and unreviewed).
  '/a',
  '/concept-studio',
  '/motion-studio',
  '/pattern-studio',
  '/ad-studio',
  // Existing public guides and supporting product surfaces.
  '/living-site',
  '/install',
  '/about',
  '/pricing',
  '/ai-use',
  '/contact',
  '/data',
  '/faq',
  '/how-it-works',
  '/hui',
  '/mana-receipts',
  '/mana-receipts/sample',
  '/press',
  '/te-tiriti',
  '/trust',
  '/trust/soc2',
  // Assembling remains a specialist journey capability, not a master product.
  '/assembling',
  '/assembling/for-ai-builders',
  '/assembling/sdk',
  '/assembling/rewards',
  '/assembling/interactive',
  '/assembling/privacy',
  '/assembling/terms',
  '/assembling/copyright',
];

export default function sitemap(): MetadataRoute.Sitemap {
  const lastModified = new Date();

  const core: MetadataRoute.Sitemap = CORE_PATHS.map((path) => ({
    url: `${BASE}${path}`,
    lastModified,
    changeFrequency: 'weekly',
    priority:
      path === ''
        ? 1
        : PRODUCT_PATHS.includes(path)
          ? 0.9
          : path.startsWith('/assembling')
            ? 0.6
            : 0.5,
  }));

  return core;
}
